 dict(id='preferences-fullness', jsx='BouquetDetailPreferences/BouquetDetailPreferences.tsx', css='BouquetDetailPreferences/BouquetDetailPreferences.module.css', consumer='BouquetDetailHero', native='radio inside label', target='.radioInput + .radioLabel', states='hover inset border and active background, existing checked mark and focus', status='implemented'),
 dict(id='preferences-extras', jsx='BouquetDetailPreferences/BouquetDetailPreferences.tsx', css='BouquetDetailPreferences/BouquetDetailPreferences.module.css', consumer='BouquetDetailHero', native='checkbox inside label', target='.checkboxInput + .checkboxLabel', states='hover inset border and active background, existing checked mark and focus', status='implemented'),
 dict(id='preferences-fields', jsx='BouquetDetailPreferences/BouquetDetailPreferences.tsx', css='BouquetDetailPreferences/BouquetDetailPreferences.module.css', consumer='BouquetDetailHero', native='text input and textarea', target='.fieldInput, .fieldTextarea', states='hover border; existing focus and date error preserved; text editing native', status='implemented'),
 dict(id='detail-information', jsx='BouquetDetailSupporting/BouquetDetailSupporting.tsx', css='BouquetDetailSupporting/BouquetDetailSupporting.module.css', consumer='BouquetDetailHero', native='details summary', target='.information summary and .chevron', states='hover/active color, existing focus, open chevron transition', status='implemented'),
 dict(id='contact-faq', jsx='ContactBlocks/ContactFaq.tsx', css='ContactBlocks/ContactFaq.module.css', consumer='ContactLower', native='button aria-expanded', target='.trigger and .sign', states='hover color, active sign scale, existing focus and expanded icon', status='implemented'),
 dict(id='bouquets-anchors', jsx='BouquetsInspiration/BouquetsInspiration.tsx', css='BouquetsInspiration/BouquetsInspiration.module.css', consumer='BouquetsPage', native='anchor fragment', target='.selector', states='hover color/border, active scale, existing focus; .all is static styling not selected state', status='implemented'),
 dict(id='bouquets-disabled-card-actions', jsx='BouquetsInspiration/BouquetsInspiration.tsx', css='BouquetsInspiration/BouquetsInspiration.module.css', consumer='BouquetsPage', native='disabled button', target='.action', states='disabled; excluded from interaction motion', status='excluded_disabled'),
